-- Work456/07: SQL seam only. Shell separately observes its actual records.
-- Full-value literal expectations come from the independently written model.
create table alt_rows(id int primary key,note int not null,payload bit varying(50000) not null storage prefer_inline);
create table alt_source(id int primary key,note int,payload bit varying(50000));
insert into alt_rows values(1,101,X'19ab23cd45ef'),(2,202,cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying));
insert into alt_rows values(1,111,cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying)),(3,303,X'19ab23cd45ef') on duplicate key update note=111,payload=cast(concat(repeat('a1',1701),repeat('b2',1703),repeat('c3',1703)) as bit varying);
-- Check the full intermediate value before id=1 is overwritten again.
select count(*) as exact_rows from alt_rows where id=1 and note=111 and payload=X'';
insert into alt_rows set id=2,note=222,payload=X'19ab23cd45ef' on duplicate key update note=222,payload=X'19ab23cd45ef';
insert into alt_source values(1,121,X'19ab23cd45ef'),(4,404,cast(concat(repeat('d4',1801),repeat('e5',1803),repeat('f6',1803)) as bit varying));
insert into alt_rows select id,note,payload from alt_source on duplicate key update note=121,payload=X'19ab23cd45ef';
select count(*) as row_count,sum(case when id=1 and note=121 and payload=X'19ab23cd45ef' then 1 when id=2 and note=222 and payload=X'19ab23cd45ef' then 1 when id=3 and note=303 and payload=X'19ab23cd45ef' then 1 when id=4 and note=404 and payload=X'' then 1 else 0 end) as exact_rows from alt_rows;
drop table alt_source;
drop table alt_rows;
